-- Master values are intentionally not unique by display name: source data contains
-- repeated product-category rows and descriptions. source_row_key identifies each
-- imported source row without collapsing valid duplicates.
CREATE TABLE IF NOT EXISTS master_tender_type (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_number_of_covers (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_tender_category (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_work_item_product_category (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_number_of_bid_openers (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_form_of_contract (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_tenderer_class (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS master_data_seed_import (
  import_key VARCHAR(255) PRIMARY KEY,
  imported_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE master_tender_type ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_tender_type ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_tender_type ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);
ALTER TABLE master_number_of_covers ALTER COLUMN name TYPE VARCHAR(255);
ALTER TABLE master_number_of_covers ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_number_of_covers ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_number_of_covers ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);
ALTER TABLE master_tender_category ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_tender_category ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_tender_category ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);
ALTER TABLE master_work_item_product_category ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_work_item_product_category ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_work_item_product_category ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);
ALTER TABLE master_work_item_product_category ADD COLUMN IF NOT EXISTS tender_category_id BIGINT REFERENCES master_tender_category(id);
ALTER TABLE master_number_of_bid_openers ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_number_of_bid_openers ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_number_of_bid_openers ADD COLUMN IF NOT EXISTS bovalue INTEGER;
ALTER TABLE master_number_of_bid_openers ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);
ALTER TABLE master_form_of_contract ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_form_of_contract ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_form_of_contract ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);
ALTER TABLE master_tenderer_class ADD COLUMN IF NOT EXISTS code VARCHAR(255);
ALTER TABLE master_tenderer_class ADD COLUMN IF NOT EXISTS description TEXT;
ALTER TABLE master_tenderer_class ADD COLUMN IF NOT EXISTS source_row_key VARCHAR(255);

ALTER TABLE master_tender_type ALTER COLUMN name TYPE VARCHAR(255);
ALTER TABLE master_tender_category ALTER COLUMN name TYPE VARCHAR(255);
ALTER TABLE master_work_item_product_category ALTER COLUMN name TYPE VARCHAR(255);
