CREATE UNIQUE INDEX IF NOT EXISTS uq_master_tender_type_source_row_key ON master_tender_type(source_row_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_master_number_of_covers_source_row_key ON master_number_of_covers(source_row_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_master_tender_category_source_row_key ON master_tender_category(source_row_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_master_work_item_product_category_source_row_key ON master_work_item_product_category(source_row_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_master_number_of_bid_openers_source_row_key ON master_number_of_bid_openers(source_row_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_master_form_of_contract_source_row_key ON master_form_of_contract(source_row_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_master_tenderer_class_source_row_key ON master_tenderer_class(source_row_key);

SELECT seed.name, seed.source_row_key
FROM (VALUES ('1 Cover', 'bootstrap:number-of-covers:1'),
             ('2 Covers', 'bootstrap:number-of-covers:2'),
             ('3 Covers', 'bootstrap:number-of-covers:3')) AS seed(name, source_row_key)
WHERE NOT EXISTS (SELECT 1 FROM master_data_seed_import WHERE import_key = 'bootstrap:number-of-covers:v1')
  AND NOT EXISTS (SELECT 1 FROM master_number_of_covers existing WHERE existing.name = seed.name)
ON CONFLICT (source_row_key) DO NOTHING;
CREATE TABLE IF NOT EXISTS pre_tender (
 id BIGSERIAL PRIMARY KEY,
 procurement_type VARCHAR(80) NOT NULL, tender_reference_number VARCHAR(180) NOT NULL,
 tender_type_id BIGINT NOT NULL REFERENCES master_tender_type(id), number_of_covers_id BIGINT NOT NULL REFERENCES master_number_of_covers(id),
 tender_category_id BIGINT NOT NULL REFERENCES master_tender_category(id), work_item_product_category_id BIGINT NOT NULL REFERENCES master_work_item_product_category(id),
 number_of_bid_openers_id BIGINT NOT NULL REFERENCES master_number_of_bid_openers(id), form_of_contract_id BIGINT NOT NULL REFERENCES master_form_of_contract(id),
 bid_validity_days INTEGER NOT NULL, cover1_description TEXT NOT NULL, cover2_description TEXT, delivery_period_days INTEGER NOT NULL,
 tenderer_class_id BIGINT NOT NULL REFERENCES master_tenderer_class(id), emd_exemption BOOLEAN NOT NULL, paper_cost_exemption BOOLEAN NOT NULL,
 tender_fee NUMERIC(14,2), tender_emd_fee NUMERIC(14,2), pre_bid_meeting BOOLEAN NOT NULL, pre_bid_meeting_address TEXT,
 tender_publishing_date_time TIMESTAMP NOT NULL, document_download_start_date_time TIMESTAMP NOT NULL,
 seek_clarification_start_date_time TIMESTAMP NOT NULL, seek_clarification_end_date_time TIMESTAMP NOT NULL,
 bid_submission_start_date_time TIMESTAMP NOT NULL, bid_submission_end_date_time TIMESTAMP NOT NULL, bid_opening_date_time TIMESTAMP NOT NULL,
 parent_work_id VARCHAR(160), parent_work_number VARCHAR(120), parent_work_description TEXT,
 nit_file_name VARCHAR(255), dtcn_file_name VARCHAR(255), other_file_name VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
ALTER TABLE pre_tender ADD COLUMN IF NOT EXISTS parent_work_id VARCHAR(160);
ALTER TABLE pre_tender ADD COLUMN IF NOT EXISTS parent_work_number VARCHAR(120);
ALTER TABLE pre_tender ADD COLUMN IF NOT EXISTS parent_work_description TEXT;

